            <div class="line" /></div> -->
          <div class="tbody">
            <van-pull-refresh v-model="refreshing" :loading-text="$t('tzjl.tzjl50')" :pulling-text="$t('tzjl.tzjl51')" :loosing-text="$t('tzjl.tzjl52')" :finished-text="$t('tzjl.tzjl53')" @refresh="onRefresh">
              <van-list
                v-model="loading"
                :finished="finished"
                :loading-text="$t('tzjl.tzjl50')"
                finished-text=""
                @load="onLoad"
              >
                <is-empty v-if="dataList.length===0" />
                <div v-for="(item,index) in dataList" :key="index" class="list">
                  <span>{{ item.uname }}</span>
                  <!-- <span :class="Number(item.winnums)>0?'yellow':(Number(item.winnums)<0?'red':'white')">{{ item.winnums }}</span> -->
                  <span>{{ item.buymons }}</span>
