</template>
<script>
import TitleLine from './modules/TitleLine'
import { teamWinReport } from '@/api/user'

export default {
  components: {
    TitleLine
  },
  //   props: {
  //     currentValue: {
  //       type: String,
  //       default: '哈希一分大小'
  //     }
  //   },
  data() {
    return {
      title: '团队流水报表',
      currentValue: '2',
      showPop: false,
      allwins: '',
      allnums: '',
      dataList: [],
      typeList: [{ name: this.$t('wdsr.wdsr45'), value: '2' }, { name: '近3天', value: '3' }, { name: '近7天', value: '7' },
        { name: '近15天', value: '15' }, { name: '本月', value: '30' }, { name: '上月', value: '60' }
      ],
      loading: false,
      finished: false,
      refreshing: false,
      pageNum: 1,
      pageSize: 10
    }
  },
  created() {
    // this.updateData()
  },
  methods: {
    open(url) {
      window.open(url)
    },
    // async updateData() {
    //   const res = await teamWinReport({ type: this.currentValue })
    //   this.allnums = res.allbuy
    //   this.allwins = res.allwin
    //   this.dataList = res.datalist
    // },
    async onLoad() { //, ucode: this.$store.getters.userInfo.ucode
      const res = await teamWinReport({ pages: this.pageNum, type: this.currentValue })
      if (this.refreshing) {
        this.dataList = []
        this.refreshing = false
      }
      this.dataList = this.dataList.concat(res.datalist)
      this.loading = false
      this.pageNum++
      if (this.dataList.length >= Number(res.totalrow)) {
        this.finished = true
      }
      this.allnums = Number(res.allbuy).toFixed(2)
      this.allwins = Number(res.allwin).toFixed(2)
    },
    onRefresh() {
      // 清空列表数据
      this.finished = false
      this.pageNum = 1
      this.refreshing = true
      // 重新加载数据
      // 将 loading 设置为 true，表示处于加载状态
      this.loading = true
      this.onLoad()
    }
    // goMore() {
    //   this.$router.push({ path: '/rechargeRecord' })
    // }
  }

}
</script>
